sys_security_acl.script:
(function () {

  if (gs.hasRole('x_1805892_compan_0.admin') || gs.hasRole('x_1805892_compan_0.instructor') || gs.hasRole('x_1805892_compan_0.user')) 
    return false;

  if (!current) return false;
  var me = gs.getUserID();

  if (current.requested_for) {
    var u = new GlideRecord('sys_user');
    if (u.get(current.requested_for) && u.manager == me) return true;
  }

  var app = new GlideRecord('sysapproval_approver');
  app.addQuery('sysapproval', current.sys_id);
  app.addQuery('approver', me);
  app.addQuery('state', 'requested_for');
  app.setLimit(1);
  app.query();
  if (app.next()) return true;

  return false;
})();
